Here is the commit message:
RDMA/mlx4: Fix mis-use of RCU in mlx4_srq_event()

Sashiko points out the radix_tree itself is RCU safe, but nothing ever
frees the mlx4_srq struct with RCU, and it isn't even accessed within the
RCU critical section. It also will crash if an event is delivered before
the srq object is finished initializing.

Use the spinlock since it isn't easy to make RCU work, use
refcount_inc_not_zero() to protect against partially initialized objects,
and order the refcount_set() to be after the srq is fully initialized.

Cc: stable@vger.kernel.org
Fixes: 30353bfc43a1 ("net/mlx4_core: Use RCU to perform radix tree lookup for SRQ")
Link: https://sashiko.dev/#/patchset/0-v2-1c49eeb88c48%2B91-rdma_udata_rep_jgg%40nvidia.com?part=5
Link: https://patch.msgid.link/r/12-v1-41f3135e5565+9d2-rdma_ai_fixes1_jgg@nvidia.com
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>

Here is the root cause:
The bug arises from a race condition and incorrect RCU usage in `mlx4_srq_event()`. The radix tree lookup uses `rcu_read_lock()` to protect the tree traversal, but the `mlx4_srq` structure is not freed via RCU (it is freed synchronously), so a returned pointer may become dangling after the RCU read lock is released, leading to use-after-free. Additionally, the event may be delivered before `mlx4_srq_alloc()` completes initialization; specifically, `refcount_set(&srq->refcount, 1)` is performed before `init_completion(&srq->free)`, and without proper ordering, a concurrent event handler can increment the refcount on a partially initialized object, causing crashes or misbehavior. The fix replaces RCU with a spinlock for safe tree access, uses `refcount_inc_not_zero()` to safely increment the refcount only if the object is already fully initialized, and reorders the refcount setup with release semantics to ensure initialization completes before the refcount becomes visible.

Here is the patch:

 void mlx4_srq_event(struct mlx4_dev *dev, u32 srqn, int event_type)
 {
 	struct mlx4_srq_table *srq_table = &mlx4_priv(dev)->srq_table;
 	struct mlx4_srq *srq;
+	unsigned long flags;

-	rcu_read_lock();
+	spin_lock_irqsave(&srq_table->lock, flags);
 	srq = radix_tree_lookup(&srq_table->tree, srqn & (dev->caps.num_srqs - 1));
-	rcu_read_unlock();
-	if (srq)
-		refcount_inc(&srq->refcount);
-	else {
+	if (!srq || !refcount_inc_not_zero(&srq->refcount))
+		srq = NULL;
+	spin_unlock_irqrestore(&srq_table->lock, flags);
+	if (!srq) {
 		mlx4_warn(dev, "Async event for bogus SRQ %08x\n", srqn);
 		return;
 	}

 	srq->event(srq, event_type);

 	if (refcount_dec_and_test(&srq->refcount))
 		complete(&srq->free);
 }


 int mlx4_srq_alloc(struct mlx4_dev *dev, u32 pdn, u32 cqn, u16 xrcd,
 		   struct mlx4_mtt *mtt, u64 db_rec, struct mlx4_srq *srq)
 {
 	struct mlx4_srq_table *srq_table = &mlx4_priv(dev)->srq_table;
 	struct mlx4_cmd_mailbox *mailbox;
 	struct mlx4_srq_context *srq_context;
 	u64 mtt_addr;
 	int err;

 	err = mlx4_srq_alloc_icm(dev, &srq->srqn);
 	if (err)
 		return err;

 	spin_lock_irq(&srq_table->lock);
 	err = radix_tree_insert(&srq_table->tree, srq->srqn, srq);
 	spin_unlock_irq(&srq_table->lock);
 	if (err)
 		goto err_icm;

 	mailbox = mlx4_alloc_cmd_mailbox(dev);
 	if (IS_ERR(mailbox)) {
 		err = PTR_ERR(mailbox);
 		goto err_radix;
 	}

 	srq_context = mailbox->buf;
 	srq_context->state_logsize_srqn = cpu_to_be32((ilog2(srq->max) << 24) |
 						      srq->srqn);
 	srq_context->logstride          = srq->wqe_shift - 4;
 	srq_context->xrcd		= cpu_to_be16(xrcd);
 	srq_context->pg_offset_cqn	= cpu_to_be32(cqn & 0xffffff);
 	srq_context->log_page_size      = mtt->page_shift - MLX4_ICM_PAGE_SHIFT;

 	mtt_addr = mlx4_mtt_addr(dev, mtt);
 	srq_context->mtt_base_addr_h    = mtt_addr >> 32;
 	srq_context->mtt_base_addr_l    = cpu_to_be32(mtt_addr & 0xffffffff);
 	srq_context->pd			= cpu_to_be32(pdn);
 	srq_context->db_rec_addr        = cpu_to_be64(db_rec);

 	err = mlx4_SW2HW_SRQ(dev, mailbox, srq->srqn);
 	mlx4_free_cmd_mailbox(dev, mailbox);
 	if (err)
 		goto err_radix;

-	refcount_set(&srq->refcount, 1);
 	init_completion(&srq->free);
+	refcount_set_release(&srq->refcount, 1);

 	return 0;

 err_radix:
 	spin_lock_irq(&srq_table->lock);
 	radix_tree_delete(&srq_table->tree, srq->srqn);
 	spin_unlock_irq(&srq_table->lock);

 err_icm:
 	mlx4_srq_free_icm(dev, srq->srqn);
 	return err;
 }
 EXPORT_SYMBOL_GPL(mlx4_srq_alloc);


